theorem MIPRE.LowDegree.BinaryPolynomial.oddTraceBits_natDegree (q e : ℕ) (hq : q.Prime) (hq2 : q ≠ 2) :
    let f := polyOfBits (nonresidueLiftBitsProg (unary q))
    let F := f.comp (X ^ (q ^ (e + 1)))
    (minpoly (ZMod 2) (evalBits (AdjoinRoot.root F)
      (oddTraceBits (unary q) (unary (q ^ (e + 1)))))).natDegree = q ^ (e + 1) := by sorry
